css:
.bite,.mouth,.cover{transform-box:fill-box}
.bite{transform-origin:center;animation:bite 3.4s ease-in-out infinite}
.mouth{transform-origin:center;animation:chew 3.4s ease-in-out infinite}
.frac{animation:pop 3.4s ease-in-out infinite}
.cover{transform-origin:right center;animation:wipe 3.6s ease-out infinite}
.cover.c2{animation-name:wipe2}
@keyframes bite{0%,22%{transform:none;opacity:1}58%{transform:translate(74px,10px) scale(.6);opacity:1}70%,100%{transform:translate(92px,14px) scale(.15);opacity:0}}
@keyframes chew{0%,50%{transform:scaleY(.25)}58%{transform:scaleY(1.5)}68%{transform:scaleY(.3)}76%{transform:scaleY(1.1)}86%,100%{transform:scaleY(.25)}}
@keyframes pop{0%,66%{opacity:0}76%,100%{opacity:1}}
@keyframes wipe{0%,10%{transform:scaleX(1)}40%,100%{transform:scaleX(0)}}
@keyframes wipe2{0%,42%{transform:scaleX(1)}70%,100%{transform:scaleX(0)}}
@media (prefers-reduced-motion:reduce){.bite{opacity:.25}.cover{transform:scaleX(0)}}
